Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$PSDefaultParameterValues['*:ErrorAction']='Stop'
function ThrowOnNativeFailure {
    if (-not $?)
    {
        throw 'Native Failure'
    }
}
$nocache=""
if($args.count -gt 0){
    $nocache=$args[0]
}
$env:GITHUBPRIVATEKEY=""
docker build -t hub.docker.internal:5000/ikomida/payments-worker-image:latest . --build-arg GITHUBPRIVATEKEY="$env:GITHUBPRIVATEKEY"  --build-arg NODEENV=devlopment $nocache
ThrowOnNativeFailure
docker push hub.docker.internal:5000/ikomida/payments-worker-image:latest
kubectl -n ikomida-worker delete deploy payments-worker
kubectl apply -f k8s-dev/deployment.yaml
